def copy_health_condition_to_status(apps, schema_editor):
    profile_model = apps.get_model('info', 'HealthProfile')
    for profile in profile_model.objects.all().only('pk', 'health_condition').iterator():
        status = [] if profile.health_condition == 'none' else [profile.health_condition]
        profile_model.objects.filter(pk=profile.pk).update(health_status=status)


def copy_health_status_to_condition(apps, schema_editor):
    profile_model = apps.get_model('info', 'HealthProfile')
    legacy_conditions = {'diabetes', 'hypertension', 'asthma', 'heart'}
    for profile in profile_model.objects.all().only('pk', 'health_status').iterator():
        statuses = profile.health_status or []
        health_condition = next(
            (status for status in statuses if status in legacy_conditions),
            'none',
        )
        profile_model.objects.filter(pk=profile.pk).update(health_condition=health_condition)


